    ["A circle has diameter 14 cm. What is its radius?",["28 cm","14 cm","7 cm","3.5 cm"],2,"Radius is half the diameter, so 14 ÷ 2 = 7 cm."],
    ["Using π = 3.14, what is the area of a circle with radius 10 cm?",["31.4 cm²","314 cm²","628 cm²","100 cm²"],1,"A = 3.14 × 10² = 314 cm²."],
    ["Using π = 3.14, what is the area of a circle with radius 7 cm?",["43.96 cm²","153.86 cm²","307.72 cm²","49 cm²"],1,"A = 3.14 × 49 = 153.86 cm²."],
    ["A circle has diameter 20 cm. Using π = 3.14, what is its area?",["62.8 cm²","125.6 cm²","314 cm²","628 cm²"],2,"The radius is 10 cm, so the area is 314 cm²."],
    ["Using π = 3.14, what is the area of a circle with radius 3 cm?",["9.42 cm²","18.84 cm²","28.26 cm²","37.68 cm²"],2,"A = 3.14 × 9 = 28.26 cm²."],
    ["Using π = 3.14, a circle has area 50.24 cm². What is its radius?",["2 cm","4 cm","6 cm","8 cm"],1,"50.24 ÷ 3.14 = 16, so r = 4 cm."],
    ["If the radius of a circle is doubled, how does its area change?",["It doubles","It triples","It becomes four times as large","It becomes eight times as large"],2,"Area depends on r², so doubling the radius multiplies area by 4."],
    ["A circle has diameter 18 cm. Using π = 3.14, what is its area?",["56.52 cm²","127.17 cm²","254.34 cm²","508.68 cm²"],2,"The radius is 9 cm, so the area is 254.34 cm²."],
    ["Using π = 3.14, a circle has area 314 cm². What is its radius?",["5 cm","10 cm","20 cm","100 cm"],1,"314 ÷ 3.14 = 100, so r = 10 cm."],
    ["Using π = 3.14, a circle has area 78.5 cm². What is its radius?",["2.5 cm","5 cm","10 cm","25 cm"],1,"78.5 ÷ 3.14 = 25, so r = 5 cm."],
    ["If the radius of a circle is tripled, how many times does its area become?",["3 times","6 times","9 times","12 times"],2,"Area is proportional to r², so tripling the radius makes area 9 times larger."],
    ["A circle has diameter 8 cm. Using π = 3.14, what is its area?",["25.12 cm²","50.24 cm²","100.48 cm²","200.96 cm²"],1,"The radius is 4 cm, so the area is 50.24 cm²."],
    ["Two circles have radii 4 cm and 8 cm. What is the ratio of their areas?",["1:2","1:4","2:1","4:1"],1,"The radius ratio is 1:2, so the area ratio is 1:4."],
    ["Using π = 3.14, what is the area of a circle with radius 6 cm?",["37.68 cm²","75.36 cm²","113.04 cm²","226.08 cm²"],2,"A = 3.14 × 36 = 113.04 cm²."],
    ["Using π = 3.14, what is the area of a circle with radius 12 cm?",["150.72 cm²","301.44 cm²","452.16 cm²","904.32 cm²"],2,"A = 3.14 × 144 = 452.16 cm²."],
    ["Using π = 3.14, what is the area of a circle with radius 2 cm?",["6.28 cm²","12.56 cm²","25.12 cm²","37.68 cm²"],1,"A = 3.14 × 4 = 12.56 cm²."],
    ["Using π = 3.14, what is the area of a circle with radius 15 cm?",["47.1 cm²","235.5 cm²","706.5 cm²","1413 cm²"],2,"A = 3.14 × 225 = 706.5 cm²."],
    ["A circle has diameter 6 cm. Using π = 3.14, what is its area?",["9.42 cm²","18.84 cm²","28.26 cm²","56.52 cm²"],2,"The radius is 3 cm, so the area is 28.26 cm²."],
    ["Using π = 3.14, which radius gives an area of 153.86 cm²?",["5 cm","6 cm","7 cm","8 cm"],2,"153.86 ÷ 3.14 = 49, so r = 7 cm."],
    ["If a circle's radius changes from 10 cm to 20 cm, what happens to its area?",["It doubles","It becomes three times as large","It becomes four times as large","It becomes eight times as large"],2,"The radius doubles, so the area becomes 2² = 4 times as large."],
    ["Using π = 3.14, by how much does the area increase when radius changes from 4 cm to 6 cm?",["62.8 cm²","87.92 cm²","113.04 cm²","163.28 cm²"],0,"The areas are 50.24 cm² and 113.04 cm²; the increase is 62.80 cm²."],
    ["A circle has diameter 30 cm. Using π = 3.14, what is its area?",["94.2 cm²","235.5 cm²","706.5 cm²","1413 cm²"],2,"The radius is 15 cm, so the area is 706.5 cm²."],
    ["Using π = 3.14, what is the area of a circle with diameter 10 cm?",["31.4 cm²","78.5 cm²","157 cm²","314 cm²"],1,"The radius is 5 cm, so the area is 78.5 cm²."],
    ["Using π = 3.14, a circle has area 200.96 cm². What is its radius?",["4 cm","6 cm","8 cm","10 cm"],2,"200.96 ÷ 3.14 = 64, so r = 8 cm."],
    ["A circle and a square have the same radius r, with the square's side equal to the circle's diameter. Which has the larger area?",["The circle","The square","They have equal area","It depends on r"],1,"The circle has area 3.14r², while the square has area 4r², so the square is larger."],
    ["A circle has radius 7 cm. What is its diameter?",["3.5 cm","7 cm","14 cm","49 cm"],2,"Diameter is twice the radius, so d = 14 cm."],
    ["A circle has radius 1 m. Using π = 3.14, what is its area?",["1 m²","2 m²","3.14 m²","6.28 m²"],2,"A = 3.14 × 1² = 3.14 m²."],
    ["Why is the area of a circle written in square units such as cm²?",["Area measures distance around the boundary","Area measures the surface inside the circle","Area measures only the radius","Area measures the diameter"],1,"Area measures a two-dimensional surface, so square units are used."]
